// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(
        address sender,
        address target,
        bool emergency,
        uint256 amount,
        uint256 epochSize,
        uint256 timeJump
    ) public {
        // Bound inputs to avoid unrealistic values
        amount = bound(amount, 1, type(uint256).max);
        epochSize = bound(epochSize, 1, 1000000);
        timeJump = bound(timeJump, 1, 1000000);
        vm.assume(sender != address(0) && sender != address(this));
        vm.assume(target != address(0));

        // Set up flash governance config with ETH as asset
        address ethAsset = 0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE;
        vm.prank(address(this));
        c.configureFlashGovernance(ethAsset, amount, 1, false);

        // Set security parameters
        vm.prank(address(this));
        c.configureSecurityParameters(1, epochSize, 50);

        // Mark sender as governed
        address[] memory governables = new address[](1);
        governables[0] = sender;
        bool[] memory isGoverned = new bool[](1);
        isGoverned[0] = true;
        vm.prank(address(this));
        c.setGoverned(governables, isGoverned);

        // Need to give sender enough ETH for the transferFrom (mocked with deal)
        vm.deal(sender, amount);

        // Warp time to satisfy epoch constraints
        vm.warp(block.timestamp + epochSize + 1);

        // Now call assertGovernanceApproved as sender
        vm.prank(sender);
        (bool success, ) = address(c).call(
            abi.encodeWithSignature("assertGovernanceApproved(address,address,bool)", sender, target, emergency)
        );

        // Check the general rule: DAO should not be zero after a successful call or even a revert
        // In the correct contract, setDAO is never called here, so DAO remains non-zero (our address)
        // In the buggy version, setDAO sets DAO to zero regardless
        // The assertion: DAO is not the zero address
        assertTrue(c.DAO() != address(0));
    }
}

